int futex_wait_requeue(u32 __user *uaddr, unsigned int flags, u32 val,
                       ktime_t *abs_time, u32 bitset, u32 __user *uaddr2)
{
    int ret;
    struct hrtimer s_timer;
    struct futex_q q = { };
    unsigned int timeout = 0;

    if (abs_time) {
        s64 timeout_ns = ktime_to_ns(ktime_sub(*abs_time, ktime_get()));
        if (timeout_ns <= 0)
            return -ETIMEDOUT;
        hrtimer_init_sleeper(&s_timer, current);
        hrtimer_start(&s_timer.hs.timer, ns_to_ktime(timeout_ns), HRTIMER_MODE_REL);
        timeout = 1;
    }

    q.pi_state = NULL;
    q.bitset = bitset;
    q.key = &uaddr->futex_key;
    q.requeue_pi = 1;

    ret = futex_wait(uaddr, flags, val, timeout ? &s_timer : NULL, &q);
    if (ret)
        goto out;

    ret = futex_requeue(uaddr2, flags, uaddr, 1, 0);
    if (ret)
        goto out;

    ret = 0;
out:
    if (timeout)
        hrtimer_cancel(&s_timer.hs.timer);
    return ret;
}

int futex_wait_requeue(u32 __user *uaddr, unsigned int flags, u32 val,
                       ktime_t *abs_time, u32 bitset, u32 __user *uaddr2)
{
    int ret = 0;
    struct hrtimer timer;
    struct futex_waiter *waiter;

    if (abs_time) {
        hrtimer_init(&timer, CLOCK_REALTIME, HRTIMER_MODE_ABS);
        timer.function = futex_hrtimer_func;
        hrtimer_set_expires(&timer, *abs_time);
        hrtimer_start(&timer);
    }

    waiter = kmalloc(sizeof(*waiter), GFP_KERNEL);
    if (!waiter) {
        ret = -ENOMEM;
        goto out;
    }

    waiter->bitset = bitset;
    waiter->uaddr = uaddr;
    waiter->uaddr2 = uaddr2;

    ret = futex_wait(uaddr, flags, val, abs_time, waiter);
    if (ret)
        goto out_free;

    ret = futex_requeue(uaddr, flags, val, bitset, uaddr2);
    if (ret)
        goto out_free;

out_free:
    kfree(waiter);
out:
    if (abs_time)
        hrtimer_cancel(&timer);

    return ret;
}

int futex_wait_requeue(u32 __user *uaddr, unsigned int flags, u32 val,
                       ktime_t *abs_time, u32 bitset, u32 __user *uaddr2) {
    struct hrtimer s_timer;
    ktime_t time;
    int ret = 0;

    if (abs_time) {
        time = *abs_time;
        hrtimer_init(&s_timer, CLOCK_MONOTONIC, HRTIMER_MODE_ABS);
        s_timer.function = futex_hrtimer_callback;
    }

    if (flags & FLAGS_SHARED) {
        ret = handle_futex_wait_sh(uaddr, val, bitset, &s_timer, flags);
    } else {
        ret = handle_futex_wait(uaddr, val, bitset, &s_timer, flags);
    }

    if (ret == -EWOULDBLOCK) {
        ret = futex_requeue(uaddr2, bitset, uaddr, val, flags);
    }

    if (abs_time) {
        hrtimer_cancel(&s_timer);
    }

    return ret;
}

#include <linux/futex.h>
#include <linux/sched.h>
#include <linux/ktime.h>

int futex_wait_requeue_pi(u32 __user *uaddr, unsigned int flags, u32 val,
                          ktime_t *abs_time, u32 bitset, u32 __user *uaddr2)
{
    int ret = 0;
    struct hrtimer sht_timer;
    struct futex_q q;
    struct futex_pi_state *pi_state = NULL;

    if ((flags & FUTEX_PRIVATE_FLAG)) {
        return -EINVAL;
    }

    if (abs_time) {
        hrtimer_init(&sht_timer, CLOCK_MONOTONIC, HRTIMER_MODE_ABS);
        sht_timer.function = NULL;
        hrtimer_set_expires(&sht_timer, ktime_get());
        hrtimer_start(&sht_timer, abs_time, HRTIMER_MODE_ABS_PINNED);
    }

    futex_init_queue(&q, current);
    q.key = FUTEX_KEY_INIT;
    futex_setup_key(uaddr, &q.key);

    q.bitset = bitset;
    q.pi_state = NULL;
    q.requeue_pi = 1;
    q.requeue_pi_key = FUTEX_KEY_INIT;
    futex_setup_key(uaddr2, &q.requeue_pi_key);

    ret = futex_wait_queue(uaddr, val, &q, abs_time, flags);

    if (ret == -EWOULDBLOCK || ret == -ETIMEDOUT) {
        futex_unqueue(&q);
        if (abs_time)
            hrtimer_cancel(&sht_timer);
        return ret;
    }

    if (ret < 0) {
        futex_unqueue(&q);
        if (abs_time)
            hrtimer_cancel(&sht_timer);
        return ret;
    }

    if (abs_time)
        hrtimer_cancel(&sht_timer);

    if (q.pi_state) {
        futex_pi_state_update(q.pi_state);
    }

    return 0;
}
